solution:
pub type Rectangle = {
  width: Float64;
  height: Float64;
}

fn area(rect: &Rectangle) -> Float64 {
  return rect.width * rect.height;
}

fn main() -> Int {
  let r = Rectangle{ width: 5.0, height: 3.0 };
  let a = area(&r);
  return a as Int;
}
